#include <stdio.h>

#define MAX_N 100
#define MAX_T 20000

int main() {
    int N;
    int t[MAX_N], v[MAX_N];
    int total_time = 0;

    scanf("%d", &N);
    for (int i = 0; i < N; i++) {
        scanf("%d", &t[i]);
        total_time += t[i];
    }
    for (int i = 0; i < N; i++) {
        scanf("%d", &v[i]);
    }

    // max_speed[time] = maximum allowed speed at that time (0..total_time)
    double max_speed[MAX_T + 1];
    for (int i = 0; i <= total_time; i++) {
        max_speed[i] = 1e9;
    }

    int time = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j <= t[i]; j++) {
            if (j == 0) {
                if (max_speed[time] > v[i]) max_speed[time] = v[i];
            } else {
                if (max_speed[time + j] > v[i]) max_speed[time + j] = v[i];
            }
        }
        time += t[i];
    }

    // Speed must be 0 at start and end
    max_speed[0] = 0;
    max_speed[total_time] = 0;

    // Forward pass: limit by acceleration from left
    double speed[MAX_T + 1];
    speed[0] = 0;
    for (int i = 1; i <= total_time; i++) {
        speed[i] = speed[i-1] + 1.0;
        if (speed[i] > max_speed[i]) speed[i] = max_speed[i];
    }

    // Backward pass: limit by acceleration from right
    double speed2[MAX_T + 1];
    speed2[total_time] = 0;
    for (int i = total_time - 1; i >= 0; i--) {
        speed2[i] = speed2[i+1] + 1.0;
        if (speed2[i] > max_speed[i]) speed2[i] = max_speed[i];
    }

    // Take minimum of forward and backward limits
    for (int i = 0; i <= total_time; i++) {
        if (speed[i] > speed2[i]) speed[i] = speed2[i];
    }

    // Calculate distance using trapezoidal integration
    double distance = 0.0;
    for (int i = 0; i < total_time; i++) {
        distance += (speed[i] + speed[i+1]) * 0.5;
    }

    printf("%.10f\n", distance);
    return 0;
}

