int main() {
    int N;
    scanf("%d", &N);
    long long t[N], v[N];
    for (int i = 0; i < N; i++) scanf("%lld %lld", &t[i], &v[i]);

    long long T = 0;
    for (int i = 0; i < N; i++) T += t[i];

    // speed[j] for j = 0..T
    double *speed = malloc((T+1) * sizeof(double));

    // Set speed limits
    // Forward pass starting from 0
    speed[0] = 0;
    long long pos = 0;
    for (int i = 0; i < N; i++) {
        for (long long j = 0; j < t[i]; j++) {
            speed[pos+1] = fmin(speed[pos] + 1, v[i]);
            pos++;
        }
    }
    // Backward pass ending at 0
    speed[T] = fmin(speed[T], 0);
    pos = T;
    for (int i = N-1; i >= 0; i--) {
        for (long long j = 0; j < t[i]; j++) {
            speed[pos-1] = fmin(speed[pos-1], speed[pos] + 1);
            pos--;
        }
    }

    double dist = 0;
    for (long long j = 0; j < T; j++) dist += speed[j];

    printf("%.10f\n", dist);
    free(speed);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static double min_double(double a, double b) { return a < b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *t = (int *)malloc(sizeof(int) * N);
    int *v = (int *)malloc(sizeof(int) * N);

    int T = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d", &t[i]);
        T += t[i];
    }
    for (int i = 0; i < N; i++) scanf("%d", &v[i]);

    /* Use 0.5-second discretization.
       Let speed[k] be the maximum possible speed at time k * 0.5.
       Total points = 2*T + 1.
    */
    int M = 2 * T;
    double *lim = (double *)malloc(sizeof(double) * (M + 1));

    for (int k = 0; k <= M; k++) lim[k] = 1e100;

    int cur = 0;
    for (int i = 0; i < N; i++) {
        for (int s = cur; s <= cur + 2 * t[i]; s++) {
            lim[s] = min_double(lim[s], (double)v[i]);
        }
        cur += 2 * t[i];
    }

    lim[0] = 0.0;
    lim[M] = 0.0;

    /* Forward pass: acceleration <= 1 m/s^2, so over 0.5 sec speed changes by <= 0.5 */
    for (int k = 0; k < M; k++) {
        lim[k + 1] = min_double(lim[k + 1], lim[k] + 0.5);
    }

    /* Backward pass */
    for (int k = M - 1; k >= 0; k--) {
        lim[k] = min_double(lim[k], lim[k + 1] + 0.5);
    }

    /* Integrate by trapezoids over each 0.5-second interval */
    double ans = 0.0;
    for (int k = 0; k < M; k++) {
        ans += (lim[k] + lim[k + 1]) * 0.25; /* average speed * 0.5 sec */
    }

    printf("%.10f\n", ans);

    free(t);
    free(v);
    free(lim);
    return 0;
}

