int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> t(N), v(N);
    for (int i = 0; i < N; i++) cin >> t[i];
    for (int i = 0; i < N; i++) cin >> v[i];

    // Total time
    int totalTime = accumulate(t.begin(), t.end(), 0);

    // Maximum possible speed at each integer time point (0..totalTime)
    const int INF = 1e9;
    vector<double> maxSpeed(totalTime + 1, INF);
    maxSpeed[0] = 0;
    maxSpeed[totalTime] = 0;

    // Apply segment speed limits
    int curTime = 0;
    for (int i = 0; i < N; i++) {
        for (int j = curTime; j <= curTime + t[i]; j++) {
            maxSpeed[j] = min(maxSpeed[j], (double)v[i]);
        }
        curTime += t[i];
    }

    // Forward pass: enforce acceleration limit (+1 per second)
    for (int i = 1; i <= totalTime; i++) {
        maxSpeed[i] = min(maxSpeed[i], maxSpeed[i-1] + 1.0);
    }

    // Backward pass: enforce deceleration limit (-1 per second)
    for (int i = totalTime - 1; i >= 0; i--) {
        maxSpeed[i] = min(maxSpeed[i], maxSpeed[i+1] + 1.0);
    }

    // Compute distance: integrate speed over each second
    double distance = 0.0;
    for (int i = 0; i < totalTime; i++) {
        // Trapezoidal integration: average of start and end speed
        distance += (maxSpeed[i] + maxSpeed[i+1]) * 0.5;
    }

    cout << fixed << setprecision(10) << distance << "\n";

    return 0;
}

