int main(){
    int n;
    cin>>n;
    vector<double> t(n+1),v(n+1);
    for(int i=1;i<=n;i++) cin>>t[i];
    for(int i=1;i<=n;i++) cin>>v[i];

    vector<double> cap(n+1);
    cap[0]=0; cap[n]=0;
    for(int i=1;i<n;i++) cap[i]=min(v[i],v[i+1]);

    for(int i=1;i<=n;i++) cap[i]=min(cap[i], cap[i-1]+t[i]);
    for(int i=n-1;i>=0;i--) cap[i]=min(cap[i], cap[i+1]+t[i+1]);

    double ans=0;
    for(int i=1;i<=n;i++){
        double s=cap[i-1], e=cap[i], ti=t[i], vi=v[i];
        double p=min(vi,(ti+s+e)/2.0);
        ans += -p*p + p*(ti+s+e) - (s*s+e*e)/2.0;
    }
    printf("%.10f\n",ans);
}

