        cin >> t[i];
        T += t[i];
    }
    for (int i = 0; i < N; i++) cin >> v[i];

    // Work in units of 0.5 seconds to avoid floating-point boundary issues.
    // Let M = total time / 0.5 = 2*T.
    int M = 2 * T;

    // limit[k] = maximum allowed speed at time k * 0.5
    vector<double> limit(M + 1, 1e18);

    // Segment speed limits
    int cur = 0;
    for (int i = 0; i < N; i++) {
        int len = 2 * t[i];
        for (int k = cur; k <= cur + len; k++) {
            limit[k] = min(limit[k], (double)v[i]);
        }
        cur += len;
    }

    // Start and end must be 0 speed
    limit[0] = 0;
    limit[M] = 0;

    // Acceleration/deceleration constraints: speed difference between adjacent
    // 0.5-second points is at most 0.5.
    for (int k = 0; k < M; k++) {
        limit[k + 1] = min(limit[k + 1], limit[k] + 0.5);
    }
    for (int k = M - 1; k >= 0; k--) {
        limit[k] = min(limit[k], limit[k + 1] + 0.5);
    }

    // Integrate by trapezoids over each 0.5-second interval.
    double ans = 0.0;
    for (int k = 0; k < M; k++) {
        ans += (limit[k] + limit[k + 1]) * 0.25; // * (0.5 / 2)
    }

    cout << fixed << setprecision(10) << ans << '\n';
    return 0;
}

