            v[i] = sc.nextInt();
        }

        int T = totalTime * 2; // double resolution for 0.5s steps
        double[] maxSpeed = new double[T + 1];
        for (int i = 0; i <= T; i++) {
            maxSpeed[i] = Double.POSITIVE_INFINITY;
        }

        int time = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j <= t[i] * 2; j++) {
                maxSpeed[time + j] = Math.min(maxSpeed[time + j], v[i]);
            }
            time += t[i] * 2;
        }

        // start and end speed must be 0
        maxSpeed[0] = 0;
        maxSpeed[T] = 0;

        // forward pass: enforce acceleration limit
        for (int i = 1; i <= T; i++) {
            maxSpeed[i] = Math.min(maxSpeed[i], maxSpeed[i - 1] + 0.5);
        }

        // backward pass: enforce deceleration limit
        for (int i = T - 1; i >= 0; i--) {
            maxSpeed[i] = Math.min(maxSpeed[i], maxSpeed[i + 1] + 0.5);
        }

        double distance = 0;
        for (int i = 0; i < T; i++) {
            distance += (maxSpeed[i] + maxSpeed[i + 1]) * 0.5 / 2.0;
        }

        System.out.printf("%.10f%n", distance);
    }
}

