import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int[] t = new int[N];
        int[] v = new int[N];

        int total = 0;
        for (int i = 0; i < N; i++) {
            t[i] = fs.nextInt();
            total += t[i];
        }
        for (int i = 0; i < N; i++) {
            v[i] = fs.nextInt();
        }

        // Work in 0.5-second units to avoid floating point issues in constraints.
        int M = total * 2;

        // max speed at each 0.5-second point
        double[] limit = new double[M + 1];
        Arrays.fill(limit, Double.POSITIVE_INFINITY);

        // Segment speed limits
        int cur = 0;
        for (int i = 0; i < N; i++) {
            int len = t[i] * 2;
            for (int j = cur; j <= cur + len; j++) {
                limit[j] = Math.min(limit[j], v[i]);
            }
            cur += len;
        }

        // Start and end must be 0
        limit[0] = 0;
        limit[M] = 0;

        // Forward pass: acceleration <= 1 m/s^2 => over 0.5 sec, speed changes by at most 0.5
        for (int i = 0; i < M; i++) {
            limit[i + 1] = Math.min(limit[i + 1], limit[i] + 0.5);
        }

        // Backward pass
        for (int i = M - 1; i >= 0; i--) {
            limit[i] = Math.min(limit[i], limit[i + 1] + 0.5);
        }

        // Integrate by trapezoids over 0.5-second intervals
        double ans = 0.0;
        for (int i = 0; i < M; i++) {
            ans += (limit[i] + limit[i + 1]) * 0.25; // average speed * 0.5 sec
        }

        System.out.printf("%.10f%n", ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
